from __future__ import annotations

import tempfile
import unittest
from pathlib import Path

from csvtool.export import export, export_rows, is_phone_header, mask_phone, mask_rows

DATA = Path(__file__).resolve().parent.parent / "data"


class MaskPhoneTest(unittest.TestCase):
    def test_masks_standard_mobile(self):
        self.assertEqual(mask_phone("13800138000"), "138****8000")

    def test_masks_country_code_and_separators(self):
        self.assertEqual(mask_phone("+86 137 0000 1122"), "+86 137****1122")
        self.assertEqual(mask_phone("0086-139-1234-5678"), "0086-139****5678")
        self.assertEqual(mask_phone("8615000001111"), "86150****1111")

    def test_keeps_non_phone_values(self):
        self.assertEqual(mask_phone("zhang@example.com"), "zhang@example.com")
        self.assertEqual(mask_phone("12345"), "12345")
        self.assertEqual(mask_phone(""), "")

    def test_already_masked_value_is_unchanged(self):
        self.assertEqual(mask_phone("138****8000"), "138****8000")

    def test_phone_header_detection(self):
        for header in ("phone", "Phone", "mobile_no", "手机号", "联系电话", "tel"):
            self.assertTrue(is_phone_header(header), header)
        for header in ("name", "email", "city", "id"):
            self.assertFalse(is_phone_header(header), header)


class MaskRowsTest(unittest.TestCase):
    def test_only_phone_columns_are_masked(self):
        rows = [
            ["id", "name", "phone", "note"],
            ["1", "张伟", "13800138000", "13800138000"],
            ["2", "李娜", "+86 139 1234 5678", "ok"],
        ]
        masked = mask_rows(rows)
        self.assertEqual(masked[1], ["1", "张伟", "138****8000", "13800138000"])
        self.assertEqual(masked[2], ["2", "李娜", "+86 139****5678", "ok"])
        # 入参不被修改。
        self.assertEqual(rows[1][2], "13800138000")

    def test_falls_back_to_scanning_when_header_is_unknown(self):
        rows = [["data"], ["13800138000"]]
        self.assertEqual(mask_rows(rows)[1], ["138****8000"])


class ExportTest(unittest.TestCase):
    def test_export_rows_masks_members(self):
        rows = export_rows(DATA / "members.csv")
        phones = [row[2] for row in rows[1:]]
        self.assertEqual(
            phones,
            ["138****8000", "139****5678", "+86 137****1122", "150****1111"],
        )

    def test_export_to_file_masks_phone(self):
        with tempfile.TemporaryDirectory() as tmp:
            out = Path(tmp) / "exported.csv"
            self.assertIsNone(export(DATA / "members.csv", out))
            text = out.read_text(encoding="utf-8")
            self.assertIn("138****8000", text)
            self.assertNotIn("13800138000", text)


if __name__ == "__main__":
    unittest.main()

